import pandas as pd


def run(inputs: dict) -> dict:
    target = inputs["target_snapshot"].copy()
    cdc = inputs["cdc_events"].copy()

    # Build per-device watermark map from the target snapshot.
    # (device_id assumed unique key in target_snapshot; if duplicates exist,
    # the last occurrence in iteration order determines the watermark.)
    watermark = {}
    for _, row in target.iterrows():
        watermark[row["device_id"]] = row["applied_event_ts"]

    # Determine which events survive the per-device watermark check:
    # event applies only if event_ts > device's current applied_event_ts.
    # New devices (no watermark) accept all events.
    def _survives(row):
        wm = watermark.get(row["device_id"], None)
        if wm is None:
            return True
        return row["event_ts"] > wm

    if len(cdc) > 0:
        mask = cdc.apply(_survives, axis=1)
        surviving = cdc[mask].copy()
    else:
        surviving = cdc.copy()

    # Among surviving events per device, the latest by (event_ts, event_seq) wins.
    if not surviving.empty:
        surviving = surviving.sort_values(["device_id", "event_ts", "event_seq"])
        winners = surviving.groupby("device_id", as_index=False).tail(1)
        winners = winners[["device_id", "reading", "event_ts"]].rename(
            columns={"event_ts": "applied_event_ts"}
        )
    else:
        winners = pd.DataFrame(columns=["device_id", "reading", "applied_event_ts"])

    # Start from the existing snapshot (carry-forward semantics), then apply
    # winners: updates existing devices' reading/applied_event_ts, and adds
    # rows for brand-new devices.
    result = target.set_index("device_id")

    for _, w in winners.iterrows():
        dev = w["device_id"]
        result.loc[dev, "reading"] = w["reading"]
        result.loc[dev, "applied_event_ts"] = w["applied_event_ts"]

    result = result.reset_index()[["device_id", "reading", "applied_event_ts"]]

    return {"new_snapshot": result}
